namespace ghidra.feature.vt.gui.wizard.add;





using docking.wizard;
using docking.wizard;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.api.util;
using ghidra.util;

/**
 * Wizard step for configuring options for the selected correlators when adding to an existing
 * version tracking session.
 */
public class OptionsStep : WizardStep<AddToSessionData> {
	private OptionsPanel panel;

	protected OptionsStep(WizardModel<AddToSessionData> model) : base(model, "Correlator Options",
			new HelpLocation("VersionTrackingPlugin", "Options_Panel"))
    {

		panel = new OptionsPanel(this.notifyStatusChanged);
	}

	/* @Override */
	public void initialize(AddToSessionData data) {
		panel.initialize(data.getCorrelators(), data.getOptions());
	}

	/* @Override */
	public bool isApplicable(AddToSessionData data) {
		Map<VTProgramCorrelatorFactory, VTOptions> options = data.getOptions();
		return !options.isEmpty();
	}

	/* @Override */
	public bool isValid() {
		return panel.hasValidOptions();
	}

	/* @Override */
	public bool canFinish(AddToSessionData data) {
		return true;
	}

	/* @Override */
	public void populateData(AddToSessionData data) {
		// stub
	}

	/* @Override */
	public bool apply(AddToSessionData data) {
		return true;
	}

	/* @Override */
	public JComponent getComponent() {
		return panel;
	}

}
